from pathlib import Path

path = Path('/home/ubuntu/alfurqan-school-management/client/src/pages/JambPractice.tsx')
source = path.read_text()
source = source.replace(
    'import { BrainCircuit, Camera, CheckCircle2, ChevronLeft, ChevronRight, Clock3, Mic, Play, Send, ShieldAlert, Sparkles, Trophy } from "lucide-react";',
    'import { BrainCircuit, Camera, CheckCircle2, ChevronLeft, ChevronRight, Clock3, Maximize2, Mic, Minimize2, Play, Send, ShieldAlert, Signal, Sparkles, Trophy } from "lucide-react";'
)
start = source.index('function AdminLiveExamMonitor()')
end = source.index('\nexport function AdminJambPractice()', start)
replacement = '''function AdminLiveExamMonitor() { const liveSessions = trpc.school.adminJambLiveSessions.useQuery(undefined, { refetchInterval: 5000 }); const [selectedAttemptId, setSelectedAttemptId] = useState<number | null>(null); const [isFullscreen, setIsFullscreen] = useState(false); const [connectionQuality, setConnectionQuality] = useState<"offline" | "connecting" | "good" | "fair" | "poor">("offline"); const selectedSession = trpc.school.adminJambLiveSession.useQuery({ attemptId: selectedAttemptId ?? 0 }, { enabled: Boolean(selectedAttemptId), refetchInterval: 5000 }); const acceptAnswer = trpc.school.adminSetJambLiveAnswer.useMutation({ onSuccess: () => { setConnectionQuality("good"); toast.success("Live camera view connected"); void liveSessions.refetch(); void selectedSession.refetch(); }, onError: error => { setConnectionQuality("poor"); toast.error(`Could not connect to live camera: ${error.message}`); } }); const remoteVideoRef = useRef<HTMLVideoElement | null>(null); const monitorFrameRef = useRef<HTMLDivElement | null>(null); const peerRef = useRef<RTCPeerConnection | null>(null); useEffect(() => { setIsFullscreen(false); setConnectionQuality(selectedAttemptId ? "connecting" : "offline"); }, [selectedAttemptId]); useEffect(() => { const onFullscreenChange = () => setIsFullscreen(document.fullscreenElement === monitorFrameRef.current); document.addEventListener("fullscreenchange", onFullscreenChange); return () => document.removeEventListener("fullscreenchange", onFullscreenChange); }, []); useEffect(() => { const offerJson = selectedSession.data?.offerJson; if (!offerJson || !selectedAttemptId) return; setConnectionQuality("connecting"); peerRef.current?.close(); const peer = new RTCPeerConnection({ iceServers: [{ urls: "stun:stun.l.google.com:19302" }] }); peerRef.current = peer; const updateQuality = () => { const state = peer.connectionState; setConnectionQuality(state === "connected" ? "good" : state === "connecting" || state === "new" ? "connecting" : state === "disconnected" ? "fair" : "poor"); }; peer.addEventListener("connectionstatechange", updateQuality); const remoteStream = new MediaStream(); peer.ontrack = event => { event.streams[0]?.getTracks().forEach(track => remoteStream.addTrack(track)); if (remoteVideoRef.current) { remoteVideoRef.current.srcObject = remoteStream; void remoteVideoRef.current.play().catch(() => undefined); } }; let cancelled = false; const waitForIce = () => peer.iceGatheringState === "complete" ? Promise.resolve() : new Promise<void>(resolve => { const onStateChange = () => { if (peer.iceGatheringState === "complete") { peer.removeEventListener("icegatheringstatechange", onStateChange); resolve(); } }; peer.addEventListener("icegatheringstatechange", onStateChange); }); void (async () => { try { await peer.setRemoteDescription(JSON.parse(offerJson) as RTCSessionDescriptionInit); const answer = await peer.createAnswer(); await peer.setLocalDescription(answer); await waitForIce(); if (!cancelled && peer.localDescription) acceptAnswer.mutate({ attemptId: selectedAttemptId, answerJson: JSON.stringify(peer.localDescription) }); } catch (error) { setConnectionQuality("poor"); if (!cancelled) toast.error(error instanceof Error ? `Could not open live camera: ${error.message}` : "Could not open live camera"); } })(); return () => { cancelled = true; peer.removeEventListener("connectionstatechange", updateQuality); peer.close(); if (peerRef.current === peer) peerRef.current = null; if (remoteVideoRef.current) remoteVideoRef.current.srcObject = null; }; }, [selectedSession.data?.offerJson, selectedAttemptId]); useEffect(() => () => { peerRef.current?.close(); }, []); const toggleFullscreen = async () => { try { if (document.fullscreenElement) await document.exitFullscreen(); else await monitorFrameRef.current?.requestFullscreen(); } catch { toast.error("Fullscreen mode is not available in this browser."); } }; const qualityLabel = connectionQuality === "good" ? "Good" : connectionQuality === "fair" ? "Fair" : connectionQuality === "poor" ? "Poor" : connectionQuality === "connecting" ? "Connecting" : "Offline"; const selected = selectedSession.data; return <section className="surface settings-card jamb-live-monitoring"><div className="section-heading-row"><div><p className="eyebrow">Administrator-only monitoring</p><h3 className="section-title">Live exam sessions</h3><p className="muted">Only students who consented to camera and microphone safeguards and are currently in an active attempt can appear here. Select a session to request a live peer-to-peer view.</p></div><span className="status active"><i />{liveSessions.data?.length ?? 0} active</span></div>{liveSessions.isLoading ? <p className="empty-state">Checking active consented sessions...</p> : !(liveSessions.data ?? []).length ? <p className="empty-state">No consented students are currently taking an exam.</p> : <div className="jamb-live-session-grid">{(liveSessions.data ?? []).map(session => <button type="button" className={`jamb-live-session-card ${selectedAttemptId === session.attemptId ? "selected" : ""}`} key={session.attemptId} onClick={() => setSelectedAttemptId(session.attemptId)}><span className="live-dot" /><span><b>{session.studentName}</b><small>{session.className} · {session.subjectName}</small><small>{session.examTitle}</small></span><span className={`status ${session.status === "live" ? "active" : "pending"}`}><i />{session.status === "live" ? "Live" : "Ready"}</span></button>)}</div>}{selectedAttemptId && selected && <div className="jamb-live-view"><div className="section-heading-row"><div><h4>{selected.studentName} · {selected.className}</h4><p className="muted">{selected.subjectName} · {selected.examTitle} · Last heartbeat {new Date(selected.lastHeartbeat).toLocaleTimeString()}</p></div><button type="button" className="filter-button" onClick={() => setSelectedAttemptId(null)}>Close view</button></div><div className={`jamb-live-video-shell ${isFullscreen ? "is-fullscreen" : ""}`} ref={monitorFrameRef}><video ref={remoteVideoRef} autoPlay playsInline muted aria-label={`Live consented exam camera for ${selected.studentName}`} /><div className="jamb-live-video-overlay"><Camera size={18} /> {selected.answerJson ? "Live view connected" : acceptAnswer.isPending ? "Connecting..." : "Requesting live view..."}</div><div className="jamb-live-video-controls"><span className={`jamb-live-quality ${connectionQuality}`}><Signal size={16} /> Connection: {qualityLabel}</span><button type="button" className="filter-button" onClick={() => void toggleFullscreen()}>{isFullscreen ? <Minimize2 size={15} /> : <Maximize2 size={15} />} {isFullscreen ? "Exit fullscreen" : "Fullscreen"}</button></div></div><p className="jamb-live-privacy"><ShieldAlert size={15} /> This is a consented live view for the active exam only. It is not recorded by the administrator view and closes when the student ends the attempt or stops sending heartbeats.</p></div>}</section> }
'''
path.write_text(source[:start] + replacement + source[end:])
print('Administrator monitor controls added')
